<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowDown, ArrowLeft, ArrowUp, Copy, Eye, LoaderCircle, Send, WandSparkles } from 'lucide-vue-next'
import { createPublicForm, getPublicFormAdmin, publishPublicForm, regeneratePublicFormToken, updatePublicForm } from '@/api/public-forms'
import PublicFormRenderer from '@/components/public-forms/PublicFormRenderer.vue'

const route = useRoute(); const router = useRouter(); const loading = ref(Boolean(route.params.id)); const saving = ref(false); const error = ref(''); const activeTab = ref('config'); const formId = ref(route.params.id || null); const publicToken = ref(''); const baseUrl = window.location.origin
const defaults = () => ({ name: '', type: 'generic', branding: { logo: '', primaryColor: '#2563eb', title: 'Queremos conhecer você', description: 'Preencha os dados abaixo.', buttonText: 'Enviar' }, fields: [{ key: 'full_name', type: 'text', label: 'Nome completo', placeholder: '', enabled: true, required: true, order: 0 }, { key: 'phone', type: 'phone', label: 'WhatsApp', placeholder: '', enabled: true, required: true, order: 1 }, { key: 'email', type: 'email', label: 'E-mail', placeholder: '', enabled: true, required: false, order: 2 }, { key: 'notes', type: 'textarea', label: 'Observações', placeholder: '', enabled: true, required: false, order: 3 }], consent: { privacy: { enabled: true, required: true, text: 'Li e concordo com a Política de Privacidade.', documentUrl: '', version: '1' }, whatsappContact: { enabled: false, required: false, text: 'Aceito receber contato por WhatsApp.', documentUrl: '', version: '1' } }, success: { title: 'Tudo certo!', message: 'Recebemos seus dados.' }, settings: { minSubmitTimeMs: 1200 } })
const draft = ref(defaults()); const previewValues = ref({}); const publishUrl = computed(() => publicToken.value ? `${baseUrl}/f/${publicToken.value}` : '')
onMounted(async () => { if (!formId.value) return; try { const { data } = await getPublicFormAdmin(formId.value); draft.value = data.form; publicToken.value = data.form.publicToken } catch { error.value = 'Não foi possível carregar este formulário.' } finally { loading.value = false } })
function payload() { return { name: draft.value.name, type: draft.value.type, branding: draft.value.branding, fields: draft.value.fields.map((field, order) => ({ ...field, order })), consent: draft.value.consent, success: draft.value.success, settings: draft.value.settings } }
async function save() { saving.value = true; error.value = ''; try { const response = formId.value ? await updatePublicForm(formId.value, payload()) : await createPublicForm(payload()); const form = response.data.form; formId.value = form._id; publicToken.value = form.publicToken; if (!route.params.id) await router.replace({ name: 'public-forms-edit', params: { id: form._id } }) } catch (err) { error.value = err.response?.data?.error?.message || err.response?.data?.message || 'Revise os dados do formulário.' } finally { saving.value = false } }
async function publish() { await save(); if (!formId.value || error.value) return; try { const { data } = await publishPublicForm(formId.value); publicToken.value = data.form.publicToken || publicToken.value; activeTab.value = 'preview' } catch (err) { error.value = err.response?.data?.error?.message || err.response?.data?.message || 'Não foi possível publicar.' } }
function move(index, direction) { const target = index + direction; if (target < 0 || target >= draft.value.fields.length) return; const fields = draft.value.fields; [fields[index], fields[target]] = [fields[target], fields[index]] }
async function copyLink() { if (publishUrl.value) await navigator.clipboard.writeText(publishUrl.value) }
async function renew() { if (!confirm('Gerar um novo link? O link anterior será invalidado imediatamente.')) return; const { data } = await regeneratePublicFormToken(formId.value); publicToken.value = data.publicUrl.split('/').pop() }
</script>

<template>
  <main class="builder"><header class="top"><button class="back" @click="router.push({ name: 'public-forms-list' })"><ArrowLeft :size="18" /> Formulários</button><div class="title"><p>Formulário público</p><h1>{{ formId ? draft.name || 'Editar formulário' : 'Novo formulário' }}</h1></div><div class="top-actions"><button class="secondary" :disabled="saving" @click="save">Salvar rascunho</button><button class="primary" :disabled="saving" @click="publish"><Send :size="16" /> Publicar</button></div></header>
    <div v-if="loading" class="loading"><LoaderCircle class="spin" /> Carregando...</div><template v-else><p v-if="error" class="error">{{ error }}</p><nav class="tabs"><button :class="{ active: activeTab === 'config' }" @click="activeTab = 'config'"><WandSparkles :size="16" /> Configurações</button><button :class="{ active: activeTab === 'preview' }" @click="activeTab = 'preview'"><Eye :size="16" /> Preview</button></nav>
      <section v-if="activeTab === 'config'" class="config"><div class="panel"><h2>Identificação</h2><label>Nome interno<input v-model="draft.name" maxlength="120" placeholder="Formulário teste" /></label><label>Tipo<select v-model="draft.type" disabled><option value="generic">Genérico</option></select></label></div><div class="panel"><h2>Aparência</h2><label>Logo (URL)<input v-model="draft.branding.logo" type="url" placeholder="Usa o logo da clínica por padrão" /></label><div class="two"><label>Cor principal<input v-model="draft.branding.primaryColor" type="color" /></label><label>Título<input v-model="draft.branding.title" maxlength="160" /></label></div><label>Descrição<textarea v-model="draft.branding.description" maxlength="1000" /></label><label>Texto do botão<input v-model="draft.branding.buttonText" maxlength="80" /></label></div><div class="panel"><h2>Campos</h2><p class="hint">Os tipos e as chaves são controlados pela engine.</p><div v-for="(field, index) in draft.fields" :key="field.key" class="field-row"><div><strong>{{ field.key === 'full_name' ? 'Nome completo' : field.key === 'phone' ? 'WhatsApp' : field.key === 'email' ? 'E-mail' : 'Observações' }}</strong><label>Rótulo<input v-model="field.label" maxlength="160" /></label><label>Placeholder<input v-model="field.placeholder" maxlength="160" /></label></div><div class="toggles"><label><input v-model="field.enabled" type="checkbox" /> Ativado</label><label><input v-model="field.required" type="checkbox" /> Obrigatório</label><div><button :disabled="index === 0" @click="move(index, -1)"><ArrowUp :size="16" /></button><button :disabled="index === draft.fields.length - 1" @click="move(index, 1)"><ArrowDown :size="16" /></button></div></div></div></div><div class="panel"><h2>Consentimentos</h2><div v-for="(consent, key) in draft.consent" :key="key" class="consent-config"><div class="toggles"><label><input v-model="consent.enabled" type="checkbox" /> {{ key === 'privacy' ? 'Privacidade' : 'Contato por WhatsApp' }}</label><label><input v-model="consent.required" :disabled="!consent.enabled" type="checkbox" /> Obrigatório</label></div><label>Texto<textarea v-model="consent.text" :disabled="!consent.enabled" maxlength="2000" /></label><div class="two"><label>Versão<input v-model="consent.version" :disabled="!consent.enabled" maxlength="50" /></label><label>Documento (HTTPS)<input v-model="consent.documentUrl" :disabled="!consent.enabled" type="url" /></label></div></div></div><div class="panel"><h2>Sucesso</h2><label>Título<input v-model="draft.success.title" /></label><label>Mensagem<textarea v-model="draft.success.message" /></label></div></section>
      <section v-else class="preview-area"><div class="link-box" v-if="publishUrl"><span>{{ publishUrl }}</span><button @click="copyLink"><Copy :size="16" /> Copiar link</button><button class="link-button" @click="renew">Gerar novo link</button></div><p v-else class="hint">Salve e publique para gerar o link público.</p><div class="preview"><div class="mini-card" :style="{ '--form-primary': draft.branding.primaryColor }"><header><p class="clinic">Sua clínica</p><h2>{{ draft.branding.title }}</h2><p>{{ draft.branding.description }}</p></header><PublicFormRenderer v-model="previewValues" :form="draft" readonly /><div v-if="draft.consent.privacy.enabled" class="preview-consent"><input type="checkbox" disabled /> {{ draft.consent.privacy.text }}</div><button :style="{ background: draft.branding.primaryColor }" disabled>{{ draft.branding.buttonText }}</button></div></div></section>
    </template></main>
</template>

<style scoped>
.builder { max-width: 1100px; margin: auto; padding: 25px 32px 50px; color: #172033; }.top { display: grid; grid-template-columns: 150px 1fr auto; align-items: center; gap: 15px; margin-bottom: 25px; }.back,.secondary,.primary,.tabs button,.link-box button { border-radius: 8px; border: 1px solid #d8e0ec; background: #fff; color: #334155; padding: 10px 12px; cursor: pointer; font: inherit; display: inline-flex; align-items:center; justify-content:center; gap:6px; }.title p { margin: 0; color: #64748b; font-size: 13px; }.title h1 { margin: 3px 0 0; font-size: 23px; }.top-actions { display: flex; gap: 9px; }.primary { background: #2563eb; border-color: #2563eb; color: white; font-weight: 650; }.error { padding: 12px; color: #991b1b; background: #fef2f2; border-radius: 9px; }.tabs { display: flex; gap: 6px; margin-bottom: 22px; }.tabs button.active { color: #1d4ed8; background: #eff6ff; border-color: #bfdbfe; }.config { display: grid; gap: 16px; }.panel { border: 1px solid #e2e8f0; border-radius: 12px; background: white; padding: 20px; display: grid; gap: 15px; }.panel h2 { margin: 0; font-size: 17px; }.panel label { display: grid; gap: 6px; color: #475569; font-size: 13px; font-weight: 650; }.panel input,.panel textarea,.panel select { box-sizing: border-box; width:100%; min-height:40px; border:1px solid #cbd5e1; border-radius:7px; padding:9px; color:#172033; font:inherit; background:#fff; }.panel textarea { min-height:78px; resize:vertical; }.two { display:grid; grid-template-columns: 1fr 1fr; gap:13px; }.two input[type=color] { padding:4px; }.hint { margin: -7px 0 0; color:#64748b; font-size:13px; }.field-row { display:grid; grid-template-columns:1fr 190px; gap:18px; padding:15px 0; border-top:1px solid #edf1f6; }.field-row>div:first-child { display:grid; gap:8px; }.toggles { display:grid; align-content:start; gap:11px; }.toggles label { display:flex; align-items:center; gap:7px; }.toggles input { width:16px; min-height:16px; }.toggles button { width:30px; height:30px; border:1px solid #cbd5e1; border-radius:6px; background:white; margin-right:5px; cursor:pointer; }.toggles button:disabled { opacity:.4; cursor:default; }.consent-config { padding-top:15px; border-top:1px solid #edf1f6; display:grid; gap:12px; }.preview-area { display:grid; gap:18px; }.link-box { padding:12px 14px; border:1px solid #bfdbfe; border-radius:10px; background:#eff6ff; display:flex; align-items:center; gap:10px; flex-wrap:wrap; color:#1e3a8a; font-size:13px; }.link-box span { flex:1; overflow-wrap:anywhere; }.link-box button { padding:7px 9px; }.link-box .link-button { color:#b91c1c; }.preview { min-height:550px; padding:35px; border-radius:13px; background:#f1f5f9; display:grid; justify-items:center; align-items:start; }.mini-card { width:min(100%,500px); background:#fff; border-radius:16px; padding:26px; box-shadow:0 10px 25px rgb(15 23 42 / .1); }.mini-card header { text-align:center; margin-bottom:23px; }.mini-card h2 { margin:5px 0; }.mini-card p { margin:5px 0; color:#64748b; }.mini-card .clinic { font-size:13px; }.preview-consent { margin:18px 0; font-size:13px; color:#475569; }.mini-card>button { width:100%; min-height:46px; color:white; border:0; border-radius:9px; font:inherit; font-weight:650; }.loading { display:flex; gap:8px; justify-content:center; padding:100px; }.spin { animation:spin 1s linear infinite; } @keyframes spin{to{transform:rotate(360deg)}} @media(max-width:700px){.builder{padding:20px 14px}.top{grid-template-columns:1fr;align-items:start}.top-actions{width:100%}.top-actions button{flex:1}.two,.field-row{grid-template-columns:1fr}.preview{padding:15px}.link-box{align-items:stretch}.link-box button{width:100%}}
</style>
